using System;using System.Globalization;using ForteMove.Web.Infrastructure;namespace ForteMove.Web.Driver{public partial class Upcoming:DriverPage{protected void Page_Load(object sender,EventArgs e){if(!IsPostBack){var items=ServiceFactory.CreateDriverOperationsService().GetUpcoming(CurrentPrincipalContext.UserAccountId);rptTrips.DataSource=items;rptTrips.DataBind();pnlEmpty.Visible=items.Count==0;}}protected string FormatDate(object value){return Convert.ToDateTime(value).ToString("ddd, dd MMM",CultureInfo.CurrentCulture);}protected string FormatTime(object value){return DateTime.Today.Add((TimeSpan)value).ToString("HH:mm",CultureInfo.CurrentCulture);}}}
